from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class PackingSlipLine:
    sku: str
    name: str
    quantity: int


@dataclass(frozen=True)
class PackingSlip:
    order_id: str
    customer_name: str
    lines: tuple[PackingSlipLine, ...]


@dataclass(frozen=True)
