    shop.catalog.handle_add_product({"sku": "MUG", "name": "Mug", "unit_price_cents": 700, "on_hand": 5})
    # LAMP sits at exactly 5, so it is not below the line.
    assert shop.fulfilment.handle_fulfilment_summary().body["low_stock_products"] == 1


